<?php
namespace App\Filament\Resources\Returns;
use App\Filament\Resources\Concerns\AdminResource; use App\Filament\Resources\Returns\Pages\ManageReturns; use App\Models\ReturnRequest; use App\Services\ReturnService;
use BackedEnum; use Filament\Actions\Action; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\SelectFilter; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder;
class ReturnRequestResource extends AdminResource { protected static ?string $model=ReturnRequest::class; protected static string $viewPermission='returns.manage'; protected static ?string $managePermission='returns.manage'; protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedArrowPath; protected static ?string $navigationLabel='Đổi trả'; protected static string|\UnitEnum|null $navigationGroup='Khách hàng & Hậu mãi'; protected static ?int $navigationSort=30; private const STATUSES=['requested'=>'Yêu cầu mới','approved'=>'Đã chấp nhận','rejected'=>'Từ chối','received'=>'Đã nhận hàng','refunded'=>'Đã hoàn tiền','closed'=>'Đã đóng']; public static function form(Schema $s):Schema{return $s->components([]);} public static function table(Table $t):Table{return $t->defaultSort('requested_at','desc')->columns([TextColumn::make('return_number')->label('Mã yêu cầu')->searchable()->weight('bold'),TextColumn::make('order_id')->label('ID đơn'),TextColumn::make('reason')->label('Lý do')->limit(55),TextColumn::make('status')->label('Trạng thái')->badge()->formatStateUsing(fn($s)=>self::STATUSES[$s]),TextColumn::make('requested_at')->label('Ngày gửi')->dateTime('d/m/Y H:i')])->filters([SelectFilter::make('status')->options(self::STATUSES)])->recordActions([self::move('approved','Chấp nhận'),self::move('rejected','Từ chối'),self::move('received','Đã nhận hàng'),self::move('refunded','Đã hoàn tiền'),self::move('closed','Đóng')]);}private static function move(string $to,string $label):Action{return Action::make('to_'.$to)->label($label)->requiresConfirmation()->action(fn(ReturnRequest $r)=>app(ReturnService::class)->transition($r,$to));}public static function canCreate():bool{return false;}public static function canEdit(\Illuminate\Database\Eloquent\Model $r):bool{return false;}public static function canDelete(\Illuminate\Database\Eloquent\Model $r):bool{return false;}public static function getPages():array{return ['index'=>ManageReturns::route('/')];}}
